using System;using System.IO;using System.Threading.Tasks;using CuckooSetup;
class Fake:IBackend,IUpdateOptions {public bool Updating;public int Launches;public bool AppRunning{get;set;}public bool ApproveRunningExit{get;set;}public Exception LaunchError;public bool IsUpdate{get{return Updating;}}public bool RuntimeMissing{get{return true;}}public bool ChildActive{get;set;}public string LogPath{get{return "test";}}public TaskCompletionSource<bool> Pending=new TaskCompletionSource<bool>();public int Calls;public Task Install(Action<string> p){Calls++;return Pending.Task;}public Task Uninstall(Action<string> p){return Install(p);}public Task Launch(){Launches++;if(LaunchError!=null)throw LaunchError;return Task.FromResult(true);}}
class RunningFake:IRunningApplication {public bool Running=true;public bool Refuse;public int Requests;public bool IsRunning{get{return Running;}}public Task RequestExit(){Requests++;if(Refuse)throw new SetupError("EXIT_TIMEOUT","pending");Running=false;return Task.FromResult(true);}}
class SetupTests {
 static int count;static void Check(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static void Main(){try{Run().GetAwaiter().GetResult();Console.WriteLine(count+" passed");}catch(Exception e){Console.Error.WriteLine(e);Environment.ExitCode=1;}}
 static async Task Run(){
  bool present=false;int invoked=0;await RuntimePreparation.Ensure(()=>present,()=>{invoked++;present=true;return Task.FromResult(0);});Check(present&&invoked==1,"missing runtime prepared");
  await RuntimePreparation.Ensure(()=>true,()=>{invoked++;return Task.FromResult(1);});Check(invoked==1,"existing runtime not changed");
  bool networkRejected=false;try{await RuntimePreparation.Ensure(()=>false,()=>Task.FromResult(12029));}catch(SetupError e){networkRejected=e.Code=="WEBVIEW2";}Check(networkRejected,"network failure is not completion");
  bool unverifiedRejected=false;try{await RuntimePreparation.Ensure(()=>false,()=>Task.FromResult(0));}catch(SetupError){unverifiedRejected=true;}Check(unverifiedRejected,"zero exit without runtime rejected");
  var f=new Fake();var flow=new Flow(f,false);var first=flow.Run();await flow.Run();Check(f.Calls==1,"single flight");Check(!flow.CanClose,"busy close blocked");f.Pending.SetResult(true);await first;Check(flow.State==Phase.Complete&&flow.CanClose,"confirmed completion");
  f=new Fake();flow=new Flow(f,false);first=flow.Run();f.Pending.SetException(new Unconfirmed("unknown"));await first;Check(flow.State==Phase.Unconfirmed,"uncertain is not success");await flow.Run();Check(f.Calls==1,"uncertain cannot retry");
  f=new Fake();flow=new Flow(f,false);first=flow.Run();f.Pending.SetException(new SetupError("NETWORK","network"));await first;Check(flow.State==Phase.Failed,"known failure");
  f=new Fake{ChildActive=true};flow=new Flow(f,false);first=flow.Run();f.Pending.SetException(new Exception("wait error"));await first;Check(flow.State==Phase.Unconfirmed&&!flow.CanClose,"active child retained after monitor failure");
  string root=Path.Combine(Path.GetTempPath(),"Cuckoo-setup-unit-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{bool denied=false;try{Safety.Child(root,"../outside");}catch(SetupError){denied=true;}Check(denied,"path escape rejected");string file=Safety.Child(root,"audio.bin");File.WriteAllText(file,"synthetic payload");var record=new FileRecord{Path="audio.bin",Size=new FileInfo(file).Length,Sha256=Safety.HashFile(file)};Safety.Verify(file,record);Check(true,"payload integrity");File.AppendAllText(file,"x");denied=false;try{Safety.Verify(file,record);}catch(SetupError){denied=true;}Check(denied,"corruption rejected");}finally{Directory.Delete(root,true);}
  string data=Path.Combine(Path.GetTempPath(),"Cuckoo-removal-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(data);try{string own=Path.Combine(data,Backend.Id),other=Path.Combine(data,Backend.Id+".dev");Directory.CreateDirectory(Path.Combine(own,"sounds","blobs"));Directory.CreateDirectory(other);File.WriteAllText(Path.Combine(own,"settings.json"),"dummy");File.WriteAllText(Path.Combine(other,"keep"),"dummy");UserDataRemoval.Remove(data);Check(!Directory.Exists(own)&&File.Exists(Path.Combine(other,"keep")),"explicit removal only production namespace");UserDataRemoval.Remove(data);Check(true,"removal idempotent");}finally{Directory.Delete(data,true);}

  var running=new RunningFake();bool rejected=false;try{await GracefulUpdate.EnsureStopped(running,false,x=>{});}catch(SetupError){rejected=true;}Check(rejected&&running.Requests==0&&running.Running,"running app requires explicit approval");
  await GracefulUpdate.EnsureStopped(running,true,x=>{});Check(!running.Running&&running.Requests==1,"approved graceful exit is confirmed");
  running=new RunningFake{Refuse=true};rejected=false;try{await GracefulUpdate.EnsureStopped(running,true,x=>{});}catch(SetupError e){rejected=e.Code=="EXIT_TIMEOUT";}Check(rejected&&running.Running&&running.Requests==1,"failed exit pauses update without termination or retry");
  running=new RunningFake{Running=false};await GracefulUpdate.EnsureStopped(running,true,x=>{});Check(running.Requests==0,"stopped app is not launched to request exit");
  f=new Fake{Updating=true,AppRunning=true};flow=new Flow(f,false);first=flow.Run(true);Check(f.ApproveRunningExit&&f.Launches==0,"approved update waits before restart");f.Pending.SetResult(true);await first;Check(flow.State==Phase.Complete&&flow.Restarted&&f.Launches==1,"successful update restarts once");
  f=new Fake{Updating=true,LaunchError=new Exception("launch failed")};flow=new Flow(f,false);first=flow.Run();f.Pending.SetResult(true);await first;Check(flow.State==Phase.Complete&&!flow.Restarted&&flow.Error=="launch failed","restart failure cannot reinstall or claim restart");
  f.LaunchError=null;await flow.Launch();Check(flow.Restarted&&flow.Error==null&&f.Launches==2,"explicit restart retry clears prior failure");
  f=new Fake{Updating=true};flow=new Flow(f,false);first=flow.Run();f.Pending.SetException(new SetupError("INSTALL","failed"));await first;Check(f.Launches==0,"failed install does not restart");
  string gateRoot=Path.Combine(Path.GetTempPath(),"Cuckoo-update-gate-test");using(var gate=new UpdateGate(gateRoot)){bool locked=false;try{using(var another=new UpdateGate(gateRoot)){}}catch(SetupError){locked=true;}Check(locked,"update gate prevents concurrent replacement");}using(var gate=new UpdateGate(gateRoot))Check(true,"update gate releases after completion");
 Check(Backend.MaintenanceCommand("C:\\dummy",false)=="\"C:\\dummy\\CuckooMaintenance.exe\" /uninstall","native maintenance registration");
 }
}
